from pathlib import Path
import json,hashlib,datetime
w=Path('.local/controle-2026-10-31');p=w/'gui-alpha43-aanmaakdatum-na';v=json.loads((p/'rapport.json').read_text());assert v['expliciet_gestopt'] and v['programma_eindcode']==-15;assert v['begindata_sha256']==v['einddata_sha256'];assert v['programmabron']['bronmanifest_sha256']==hashlib.sha256((w/'native-alpha43-testbron.json').read_bytes()).hexdigest()
for s in v['stappen']:assert hashlib.sha256((p/s['beeld']['bestand']).read_bytes()).hexdigest()==s['beeld']['sha256']
f=p/'Nieuw-notitieboek.json';b=f.read_bytes();h=hashlib.sha256(b).hexdigest();assert h=='c39c8cc6be54c175c037be585534c9faa6710521528fd15bbe57f2a796adad13';assert b==(p/('notitiebron-'+h+'.json')).read_bytes();d=json.loads(b);pagina=d['boeken'][0]['secties'][0]['paginas'][0];tijd=datetime.datetime.fromisoformat(pagina['bijgewerkt'].replace('Z','+00:00'));start=datetime.datetime.fromisoformat(v['systeem_utc_start']);eind=datetime.datetime.fromisoformat(v['systeem_utc_eind']);assert start<=tijd<=eind and tijd.date()==datetime.date(2026,11,2)
assert pagina['titel']=='Nieuwe pagina' and pagina['markdown']=='# Nieuwe pagina\n\nSchrijf hier je notities.'
focus=json.loads((p/'focus-na-dialoog.json').read_text());assert focus['focus_voor']['id']!=focus['focus_na']['id']
u={'omvang':'Eerste alpha43-klokbron in eigen Linux-debugvenster. Nieuwe pagina toont visueel 2 nov.; werkelijk via GTK bewaard en na sluiten met de tabknop via GTK heropend. Opgeslagen bron en tijdstempel blijven exact. Ctrl+W blijkt nog niet aangesloten; die route is afgekeurd. In Xvfb zonder windowmanager is app-/dialoogfocus expliciet aangebracht; geen bewijs voor automatische focus in een normaal venstersysteem.','zichtbare_datum_visueel_geslaagd':True,'opgeslagen_tijdstempel':pagina['bijgewerkt'],'opslag_en_heropenen_bytegelijk':True,'notitie_sha256':h,'sneltoets_ctrl_w_geslaagd':False,'voorbeeldenbron_bytegelijk':True,'stappen':len(v['stappen']),'programmasource_manifest_sha256':v['programmabron']['bronmanifest_sha256']};(p/'datum-en-broncontrole.json').write_text(json.dumps(u,ensure_ascii=False,indent=2)+'\n');print(json.dumps(u,ensure_ascii=False))
